// src/utils/emit-error.ts
function pickString(...values) {
  return values.find((v) => typeof v === "string" && v.length > 0);
}
async function parseResponseBody(error) {
  if (!error || typeof error !== "object") {
    return;
  }
  const text = error.response?.text;
  if (typeof text !== "function") {
    return;
  }
  try {
    const parsed = JSON.parse(await text());
    if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
      return parsed;
    }
  } catch {}
  return;
}
async function emitError(error, message) {
  const details = await extractErrorDetails(error);
  const body = await parseResponseBody(error);
  let instructions = details.message;
  const prefixed = instructions.match(/^HTTP \d+: ([\s\S]*)$/);
  if (prefixed) {
    instructions = pickString(body?.Message, body?.message, body?.errorMessage, body?.title) ?? prefixed[1];
  }
  let context = details.context;
  const backendCode = pickString(body?.Code, body?.code, body?.errorCode);
  if (backendCode && !context?.errorCode) {
    context = { ...context, errorCode: backendCode };
  }
  OutputFormatter.error({
    Result: details.result,
    ErrorCode: details.errorCode,
    Message: message,
    Instructions: instructions,
    Retry: details.retry,
    ...context ? { Context: context } : {}
  });
}

// src/commands/data-types.ts
function parseChoicesJson(raw) {
  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    throw new Error(`--choices is not valid JSON: ${e instanceof Error ? e.message : String(e)}`);
  }
  if (!Array.isArray(parsed)) {
    throw new Error("--choices must be a JSON array");
  }
  const result = [];
  for (const [i, item] of parsed.entries()) {
    if (typeof item !== "object" || item === null) {
      throw new Error(`--choices[${i}] must be an object`);
    }
    const obj = item;
    if (typeof obj.value !== "string") {
      throw new Error(`--choices[${i}].value must be a string`);
    }
    if (obj.alternates !== undefined && !Array.isArray(obj.alternates)) {
      throw new Error(`--choices[${i}].alternates must be an array of strings when provided`);
    }
    result.push({
      Value: obj.value,
      ...obj.alternates !== undefined && {
        Alternates: obj.alternates
      }
    });
  }
  return result;
}
