// src/utils/document-files.ts
var SUPPORTED_DOCUMENT_EXTENSIONS = new Set([
  ".pdf",
  ".png",
  ".jpg",
  ".jpeg",
  ".gif",
  ".tif",
  ".tiff",
  ".bmp"
]);
function getExtension(filename) {
  const i = filename.lastIndexOf(".");
  return i < 0 ? "" : filename.slice(i).toLowerCase();
}

// src/commands/documents.ts
var MIME_TO_EXT = {
  "application/pdf": ".pdf",
  "image/png": ".png",
  "image/jpeg": ".jpg",
  "image/gif": ".gif",
  "image/tiff": ".tif",
  "image/bmp": ".bmp"
};
function extensionForContentType(contentType) {
  const mime = contentType.split(";")[0].trim().toLowerCase();
  return MIME_TO_EXT[mime] ?? null;
}
function applyDetectedExtension(targetPath, detectedExt) {
  if (!detectedExt)
    return targetPath;
  const lower2 = targetPath.toLowerCase();
  const dotIndex = targetPath.lastIndexOf(".");
  const currentExt = dotIndex >= 0 ? lower2.slice(dotIndex) : "";
  if (currentExt === detectedExt)
    return targetPath;
  if (currentExt === ".jpeg" && detectedExt === ".jpg")
    return targetPath;
  if (currentExt === ".tiff" && detectedExt === ".tif")
    return targetPath;
  if (SUPPORTED_DOCUMENT_EXTENSIONS.has(currentExt)) {
    return targetPath.slice(0, dotIndex) + detectedExt;
  }
  return targetPath + detectedExt;
}
function defaultDownloadPath() {
  const fs = getFileSystem();
  return fs.path.join(fs.env.tmpdir(), "ixp_document");
}
