// src/commands/groups.ts
function parseFieldsJson(raw) {
  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    throw new Error(`--fields is not valid JSON: ${e instanceof Error ? e.message : String(e)}`);
  }
  if (!Array.isArray(parsed)) {
    throw new Error("--fields must be a JSON array");
  }
  if (parsed.length === 0) {
    throw new Error("--fields must contain at least one field");
  }
  const result = [];
  for (const [i, item] of parsed.entries()) {
    if (typeof item !== "object" || item === null) {
      throw new Error(`--fields[${i}] must be an object`);
    }
    const obj = item;
    if (typeof obj.name !== "string" || obj.name.length === 0) {
      throw new Error(`--fields[${i}].name is required and must be a non-empty string`);
    }
    if (typeof obj.type !== "string" || obj.type.length === 0) {
      throw new Error(`--fields[${i}].type is required and must be a non-empty string`);
    }
    if (typeof obj.instructions !== "string" || obj.instructions.length === 0) {
      throw new Error(`--fields[${i}].instructions is required and must be a non-empty string`);
    }
    result.push({
      Name: obj.name,
      Type: obj.type,
      Instructions: obj.instructions
    });
  }
  return result;
}
function parseUpdatesJson(raw) {
  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    throw new Error(`--updates is not valid JSON: ${e instanceof Error ? e.message : String(e)}`);
  }
  if (!Array.isArray(parsed)) {
    throw new Error('--updates must be a JSON array, e.g. [{"name":"Invoice","instructions":"..."}]');
  }
  const result = [];
  for (const [i, item] of parsed.entries()) {
    if (typeof item !== "object" || item === null) {
      throw new Error(`--updates[${i}] must be an object`);
    }
    const obj = item;
    if (typeof obj.name !== "string" || obj.name.length === 0) {
      throw new Error(`--updates[${i}].name is required and must be a non-empty string`);
    }
    if (typeof obj.instructions !== "string") {
      throw new Error(`--updates[${i}].instructions is required and must be a string`);
    }
    result.push({ Name: obj.name, Instructions: obj.instructions });
  }
  return result;
}
